const page = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer">
<title>Hardware Deal Watch</title>
<style>
 :root{color-scheme:dark;font-family:system-ui,-apple-system,sans-serif;background:#111827;color:#e5e7eb}body{margin:0;background:linear-gradient(135deg,#111827,#172554);min-height:100vh}main{max-width:1180px;margin:auto;padding:32px 20px 56px}h1{margin:0 0 6px;font-size:clamp(1.8rem,4vw,3rem)}h2{margin-top:30px}.muted{color:#9ca3af}.panel{background:#1f2937dd;border:1px solid #374151;border-radius:16px;padding:18px;box-shadow:0 10px 30px #0003}.status{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:20px 0}.pill{border-radius:999px;padding:5px 11px;font-weight:700;font-size:.82rem}.ready{background:#064e3b;color:#a7f3d0}.error,.stale{background:#78350f;color:#fde68a}.empty,.missing,.malformed{background:#374151;color:#d1d5db}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}select,button,input,textarea{background:#111827;color:#e5e7eb;border:1px solid #4b5563;border-radius:8px;padding:9px 11px}button{cursor:pointer}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #60a5fa;outline-offset:2px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}.card{background:#111827;border:1px solid #374151;border-radius:12px;padding:15px}.card h3{margin:0 0 8px;font-size:1.05rem}.card a{color:#93c5fd}.meta{color:#cbd5e1;font-size:.92rem;margin:5px 0}.summary{color:#a7f3d0;font-size:.9rem}.diagnostic{border-left:4px solid #d97706}.change-list{margin:8px 0;padding-left:16px;font-size:.9rem}.change-price-decrease{color:#86efac}.change-price-increase{color:#fca5a5}.change-availability{color:#fde68a}.change-badge{display:inline-block;border:1px solid #4b5563;border-radius:999px;padding:3px 8px;margin:2px 4px 2px 0;font-size:.78rem}.listing-details{margin-top:12px;border-top:1px solid #374151;padding-top:8px}.listing-details summary{cursor:pointer;font-weight:700;color:#bfdbfe}.report-evidence{border-left:3px solid #22c55e;padding-left:10px;margin-top:10px}.user-review{border-left:3px solid #a78bfa;padding-left:10px}.review-box{margin-top:12px;padding-top:10px;border-top:1px solid #374151}.review-box textarea{display:block;width:100%;box-sizing:border-box;min-height:58px;margin:7px 0;resize:vertical}.select-listing{display:block;margin-bottom:10px;color:#cbd5e1;font-size:.85rem}.triage-active{border-color:#60a5fa;background:#1e3a8a}.bulk-toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:12px 0;padding:12px;border:1px solid #4b5563;border-radius:10px}.listing-thumb-wrap{width:96px;height:72px;flex:0 0 96px;border-radius:8px;overflow:hidden;background:#1f2937;display:flex;align-items:center;justify-content:center;color:#9ca3af;font-size:.72rem;text-align:center}.listing-thumb{display:block;width:96px;height:72px;object-fit:cover}.thumb-fallback{padding:4px}.thumbnails-hidden .listing-thumb-wrap{display:none}.hidden{display:none}.warning{color:#fde68a}.empty-state{padding:24px;text-align:center;color:#cbd5e1}
 </style></head><body><main><h1>Hardware Deal Watch</h1><div class="muted">Local-only view of existing watcher reports. No Facebook/MCP calls or writes.</div><section class="panel status"><span id="status" class="pill">Loading…</span><span id="message"></span><span class="muted" id="run"></span></section><section class="panel" id="newSinceLastRun"><h2>New since last run</h2><p class="muted" id="newSinceNote">Comparing saved listing IDs and bounded listing fields only.</p><p class="muted" id="newSinceRun"></p><div class="grid"><div><h3>Newly found</h3><div id="newListings"></div></div><div><h3>Updated listings</h3><div id="updatedListings"></div></div></div></section><section class="panel"><div class="controls"><label>Target <select id="category"><option value="all">All targets</option><option value="Mac Studio">Mac Studio</option><option value="Proxmox">Proxmox</option></select></label><label>Sort <select id="sort"><option value="rank">Best rank</option><option value="price">Price</option><option value="distance">Distance</option><option value="newest">Newest run</option></select></label><button id="refresh">Refresh reports</button></div><h2 id="bestHeading">Best matches</h2><p class="muted" id="bestNote">Only explicit in-radius, known-price, evidence-backed matches appear here.</p><div class="grid"><div><h3>Mac Studio</h3><div id="macDeals"></div></div><div><h3>Proxmox — complete systems</h3><div id="proxmoxComplete"></div><h3>Proxmox — components</h3><div id="proxmoxComponents"></div></div></div></section><section class="panel"><h2>Diagnostics</h2><p class="muted">Raw, unverified, out-of-radius, stale, legacy, incomplete-system, and excluded listings are never included in Best matches.</p><div id="issues"></div><div id="diagnostics" class="grid"></div></section></main>
<script>
let data={candidates:[],diagnostics:[]};
let selectedIds=new Set();
let triageFilter='all';
const $=(id)=>document.getElementById(id);
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reviewRank={Unreviewed:0,Interested:1,Verify:2,Passed:3,Acquired:4};
function checklistText(item){const checks=(item.nextChecks||[]).map(x=>'- [ ] '+x);return ['Hardware Watch manual review checklist','Listing: '+item.title,'Reported price: '+item.price,'Reported location: '+item.location+' — '+item.distanceLabel,'Evidence-based checks:',...(checks.length?checks:['- [ ] No additional checks recorded in the report.'])].join('\\n')}
function changeBadges(item){const badges=[];if(item.changeType==='new')badges.push('<span class="change-badge">New</span>');for(const kind of new Set((item.fieldChanges||[]).map(x=>x.kind))){if(kind==='price_decrease')badges.push('<span class="change-badge change-price-decrease">Price drop</span>');if(kind==='price_increase')badges.push('<span class="change-badge change-price-increase">Price increase</span>');if(kind==='availability')badges.push('<span class="change-badge change-availability">Availability changed</span>')}return badges.join('')}
function card(item,diagnostic=false){const badges=changeBadges(item);const checklist=esc(checklistText(item));const thumbnail=item.imageUrl?'<div class="listing-thumb-wrap"><img class="listing-thumb" src="'+esc(item.imageUrl)+'" alt="Thumbnail for '+esc(item.title)+'" loading="lazy" decoding="async" width="96" height="72" referrerpolicy="no-referrer" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="thumb-fallback" hidden>Thumbnail unavailable</span></div>':'<div class="listing-thumb-wrap"><span class="thumb-fallback">No thumbnail in saved report</span></div>';return '<article data-review-card data-review-id="'+esc(item.id)+'" class="card '+(diagnostic?'diagnostic':'')+'">'+thumbnail+'<h3><a href="'+esc(item.url)+'" target="_blank" rel="noreferrer">'+esc(item.title)+'</a></h3><div class="meta"><b>'+esc(item.price)+'</b> · '+esc(item.category)+' · Review: '+esc(item.reviewStatus||'Unreviewed')+'</div><div class="meta">'+esc(item.location)+' · '+esc(item.distanceLabel)+'</div>'+(badges?'<div aria-label="Listing changes">'+badges+'</div>':'')+'<details class="listing-details" data-listing-details><summary>Show evidence and review details</summary><div class="report-evidence"><div class="meta"><b>Report facts</b></div>'+(item.changeSummary?'<div class="meta warning"><b>Change:</b> '+esc(item.changeSummary)+'</div>':'')+(item.fieldChanges?.length?'<ul class="change-list">'+item.fieldChanges.map(change=>'<li class="change-'+esc(change.kind)+'"><b>'+esc(change.field)+':</b> '+esc(change.previous)+' → '+esc(change.current)+'</li>').join('')+'</ul>':'')+(item.proxmoxGroup?'<div class="meta">Proxmox lead group: '+esc(item.proxmoxGroup.replace('_',' '))+'</div>':'')+(item.priceAssessment?'<div class="meta">Price evidence: '+esc(item.priceAssessment)+'</div>':'')+'<div class="summary">'+esc(item.matchSummary)+'</div><div class="meta">Target fit: '+esc(item.targetFit)+'</div><div class="meta">Location confidence: '+esc(item.locationConfidence)+'</div>'+(item.missingSpecs?.length?'<div class="meta warning">Missing/important: '+esc(item.missingSpecs.join(', '))+'</div>':'')+(diagnostic?'<div class="meta warning">Status: '+esc(item.distanceStatus)+'</div>':'')+(item.proxmoxBuildFit?'<div class="meta">Build fit: '+esc(item.proxmoxBuildFit)+'</div>':'')+(item.additionalParts?.length?'<div class="meta warning">Additional parts/upgrades: '+esc(item.additionalParts.join(' · '))+'</div>':'')+(item.totalBuildCost?'<div class="meta warning">Total build cost: '+esc(item.totalBuildCost)+'</div>':'')+(item.nextChecks?.length?'<div class="meta warning"><b>Next checks:</b> '+esc(item.nextChecks.join(' · '))+'</div>':'')+'</div><div class="user-review"><div class="meta"><b>Your review data</b> — manual only; not report facts.</div><button type="button" data-copy-checklist data-checklist="'+checklist+'">Copy checklist</button><span class="meta" data-copy-message></span></div></details></article>'}
function changeFor(id){return [...(data.newSinceLastRun?.newListings||[]),...(data.newSinceLastRun?.updatedListings||[])].find(x=>x.id===id)}
function matchesTriage(item){if(triageFilter==='all')return true;if(['Interested','Verify','Unreviewed','Passed','Acquired'].includes(triageFilter))return item.reviewStatus===triageFilter;const change=changeFor(item.id);if(!change)return false;if(triageFilter==='new')return change.changeType==='new';if(triageFilter==='price_drop')return change.fieldChanges.some(x=>x.kind==='price_decrease');return change.fieldChanges.some(x=>x.kind==='availability'&&x.current==='Available')}
function decorateSelection(){document.querySelectorAll('[data-review-card]').forEach(cardElement=>{if(!cardElement.querySelector('[data-select-listing]'))cardElement.insertAdjacentHTML('afterbegin','<label class="select-listing"><input type="checkbox" data-select-listing> Select for bulk review</label>');const box=cardElement.querySelector('[data-select-listing]');box.checked=selectedIds.has(cardElement.dataset.reviewId);box.onchange=()=>{if(box.checked)selectedIds.add(cardElement.dataset.reviewId);else selectedIds.delete(cardElement.dataset.reviewId);updateBulkBar()}});updateBulkBar()}
function updateBulkBar(){const count=$('selectedCount');if(count)count.textContent=selectedIds.size+' selected'}
function render(){const cat=$('category').value;const review=$('reviewStatus').value;const sort=$('sort').value;const allChanges=[...(data.newSinceLastRun?.newListings||[]),...(data.newSinceLastRun?.updatedListings||[])];const filterSort=(source)=>{const result=source.filter(x=>(cat==='all'||x.category===cat)&&(review==='all'||x.reviewStatus===review)&&matchesTriage(x)).slice();result.sort((a,b)=>sort==='distance'?((a.distanceKm??Infinity)-(b.distanceKm??Infinity)):sort==='newest'?((Date.parse(b.runAt||'')||0)-(Date.parse(a.runAt||'')||0)):sort==='price'?((a.priceValue??Infinity)-(b.priceValue??Infinity)):sort==='review'?((reviewRank[a.reviewStatus]??0)-(reviewRank[b.reviewStatus]??0)):((b.rankScore??0)-(a.rankScore??0)));return result};const items=filterSort(data.candidates);const mac=items.filter(x=>x.category==='Mac Studio');const proxComplete=items.filter(x=>x.category==='Proxmox'&&x.proxmoxGroup==='complete_computer');const proxComponents=items.filter(x=>x.category==='Proxmox'&&x.proxmoxGroup==='component');const changes=data.newSinceLastRun||{status:'missing_history',message:'No saved report history is available.',runAt:null,previousRunAt:null,newListings:[],updatedListings:[]};const changesHtml=(source)=>{const list=filterSort(source);list.sort((a,b)=>(a.changePriority??99)-(b.changePriority??99));return list.length?list.map(x=>card(x,x.distanceStatus!=='in_radius'||!x.isCandidate)).join(''):'<div class="empty-state">No listings match the selected filters in this group.</div>'};const noHistory=changes.status==='first_run'||changes.status==='missing_history'||changes.status==='error';$('activeFilters').textContent='Active filters: '+[triageFilter==='all'?'none':triageFilter,cat==='all'?'all targets':cat,review==='all'?'all review statuses':review].join(' · ');document.querySelectorAll('[data-triage]').forEach(button=>button.classList.toggle('triage-active',button.dataset.triage===triageFilter));$('newSinceNote').textContent=changes.message||'No saved report history is available.';$('newSinceRun').textContent=changes.runAt?'Compared run '+new Date(changes.runAt).toLocaleString()+(changes.previousRunAt?' with '+new Date(changes.previousRunAt).toLocaleString():''):'No comparable run history.';$('newListings').innerHTML=noHistory?'<div class="empty-state">No reliable previous snapshot is available.</div>':changesHtml(changes.newListings);$('updatedListings').innerHTML=noHistory?'<div class="empty-state">No reliable previous snapshot is available.</div>':changesHtml(changes.updatedListings);$('bestHeading').textContent=data.bestSectionTitle||'Best matches';$('bestNote').textContent=data.bestSectionNote||'Only explicit in-radius, known-price, evidence-backed matches appear here.';$('macDeals').innerHTML=mac.length?mac.map(x=>card(x)).join(''):'<div class="empty-state">No Mac Studio listings match the selected filters.</div>';$('proxmoxComplete').innerHTML=proxComplete.length?proxComplete.map(x=>card(x)).join(''):'<div class="empty-state">No complete computer candidates match the selected filters.</div>';$('proxmoxComponents').innerHTML=proxComponents.length?proxComponents.map(x=>card(x)).join(''):'<div class="empty-state">No verified components match the selected filters.</div>';$('diagnostics').innerHTML=data.diagnostics.filter(matchesTriage).length?data.diagnostics.filter(matchesTriage).map(x=>card(x,true)).join(''):'<div class="empty-state">No diagnostic listings match the selected filters.</div>';decorateSelection()}
async function refresh(){try{const response=await fetch('/api/state',{cache:'no-store'});data=await response.json();const status=$('status');status.textContent=String(data.status||'unknown').toUpperCase();status.className='pill '+(data.status||'malformed');$('message').textContent=data.statusMessage||'';$('run').textContent=data.latestRunAt?'Latest run: '+new Date(data.latestRunAt).toLocaleString():'No completed run';$('issues').innerHTML=(data.issues||[]).map(x=>'<p class="warning">'+esc(x)+'</p>').join('');render()}catch(error){$('status').textContent='LOAD ERROR';$('status').className='pill error';$('message').textContent='Could not load local reports.';$('newSinceNote').textContent='Could not load saved report history.';$('newSinceRun').textContent='';$('newListings').innerHTML='<div class="empty-state">Could not load local reports.</div>';$('updatedListings').innerHTML='<div class="empty-state">Could not load local reports.</div>';$('bestHeading').textContent='Best matches unavailable';$('bestNote').textContent=String(error.message||error);$('macDeals').innerHTML='<div class="empty-state">Could not load local reports.</div>';$('proxmoxComplete').innerHTML='<div class="empty-state">Could not load local reports.</div>';$('proxmoxComponents').innerHTML='<div class="empty-state">Could not load local reports.</div>';$('diagnostics').innerHTML='';}}
$('category').onchange=render;$('reviewStatus').onchange=render;$('sort').onchange=render;$('refresh').onclick=refresh;document.querySelectorAll('[data-triage]').forEach(button=>button.onclick=()=>{triageFilter=button.dataset.triage;render()});$('resetFilters').onclick=()=>{triageFilter='all';$('category').value='all';$('reviewStatus').value='all';render()};refresh();
</script></body></html>`;

const configPanel = String.raw`<details class="panel section-fold" id="nextRunConfig" data-layout-key="configuration"><summary>Configuration <span class="section-count">next run</span></summary><div class="section-body"><h2 class="section-heading">Next run configuration</h2><p class="muted">Prepare a local pending configuration. It never runs searches or changes the active schedule until you explicitly apply it.</p><div id="configStatus" class="warning"></div><div id="configTarget" class="meta"></div><div id="queryEditor"></div><div class="controls"><button id="addQuery" type="button">Add query</button><button id="savePending" type="button">Save pending configuration</button><button id="applyPending" type="button">Apply for next run</button><button id="discardPending" type="button">Discard pending configuration</button><button id="revertApplied" type="button">Revert last applied</button></div><div id="configDiff" class="meta"></div><div id="rateEstimate" class="meta"></div></div></details>`;
const configScript = String.raw`<script>
let configState=null;
const configEsc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const configNum=(v)=>v===''?null:Number(v);
function queryRow(q,index){return '<div class="card" data-query-index="'+index+'"><div class="controls"><select data-field="kind"><option value="mac"'+(q.kind==='mac'?' selected':'')+'>Mac Studio</option><option value="proxmox"'+(q.kind==='proxmox'?' selected':'')+'>Proxmox</option></select><input data-field="query" value="'+configEsc(q.query)+'" aria-label="Query '+(index+1)+'" placeholder="Search query"><input data-field="limit" type="number" min="1" max="50" value="'+q.limit+'" aria-label="Limit '+(index+1)+'"><input data-field="maxPages" type="number" min="1" max="3" value="'+q.maxPages+'" aria-label="Pages '+(index+1)+'"><input data-field="minPrice" type="number" min="0" step="0.01" value="'+(q.minPrice??'')+'" aria-label="Minimum price '+(index+1)+'" placeholder="min $"><input data-field="maxPrice" type="number" min="0" step="0.01" value="'+(q.maxPrice??'')+'" aria-label="Maximum price '+(index+1)+'" placeholder="max $"><button type="button" data-action="up">↑</button><button type="button" data-action="down">↓</button><button type="button" data-action="remove">Remove</button></div></div>'}
function readConfig(){const rows=[...document.querySelectorAll('[data-query-index]')];return {...configState.editing,queries:rows.map(row=>{const get=(field)=>row.querySelector('[data-field="'+field+'"]')?.value??'';return {kind:get('kind'),query:get('query'),limit:Number(get('limit')),maxPages:Number(get('maxPages')),minPrice:configNum(get('minPrice')),maxPrice:configNum(get('maxPrice'))}})}}
function renderConfig(){const c=configState.pending||configState.active;configState.editing=c;document.getElementById('queryEditor').innerHTML=c.queries.map(queryRow).join('');document.getElementById('configTarget').textContent='Churchville center: '+c.center.latitude+', '+c.center.longitude+' · radius: '+c.radiusKm+' km · Mac target: '+c.targets.macStudio+' · Proxmox target: '+c.targets.proxmox;document.getElementById('configDiff').textContent='Differences: '+(configState.diff||[]).join(' | ');document.getElementById('rateEstimate').textContent=configState.rateSummary||'';document.getElementById('configStatus').textContent=configState.pending?'Pending configuration saved locally. Apply requires explicit confirmation.':'No pending configuration saved. Active configuration remains unchanged.';document.getElementById('applyPending').disabled=!configState.pending;document.getElementById('discardPending').disabled=!configState.pending;document.getElementById('revertApplied').disabled=!configState.hasBackup;}
async function loadConfig(){const r=await fetch('/api/config',{cache:'no-store'});if(!r.ok)throw new Error(await r.text());configState=await r.json();renderConfig()}
async function saveConfig(){const config=readConfig();const r=await fetch('/api/config/pending',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(config)});const body=await r.json();if(!r.ok)throw new Error(body.error||'Configuration was rejected.');configState=body;renderConfig()}
async function applyConfig(){if(!confirm('Apply this configuration for the next scheduled run? This does not run the watcher or change the schedule.'))return;const r=await fetch('/api/config/apply',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({confirmation:'APPLY_NEXT_RUN'})});const body=await r.json();if(!r.ok)throw new Error(body.error||'Configuration was not applied.');configState=body;renderConfig()}
async function discardConfig(){if(!confirm('Discard the pending configuration? This deletes only the local pending draft and does not change the active configuration, backups, schedule, reports, or review data.'))return;const r=await fetch('/api/config/discard',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({confirmation:'DISCARD_PENDING'})});const body=await r.json();if(!r.ok)throw new Error(body.error||'Pending configuration was not discarded.');configState=body;renderConfig()}
async function revertConfig(){if(!confirm('Revert the last applied configuration using its local backup?'))return;const r=await fetch('/api/config/revert',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({confirmation:'REVERT_LAST_APPLIED'})});const body=await r.json();if(!r.ok)throw new Error(body.error||'Configuration was not reverted.');configState=body;renderConfig()}
function configError(e){document.getElementById('configStatus').textContent='Configuration error: '+e.message}
document.getElementById('queryEditor').addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b)return;const row=b.closest('[data-query-index]');const i=Number(row.dataset.queryIndex);const c=readConfig();if(b.dataset.action==='remove')c.queries.splice(i,1);if(b.dataset.action==='up'&&i>0)[c.queries[i-1],c.queries[i]]=[c.queries[i],c.queries[i-1]];if(b.dataset.action==='down'&&i<c.queries.length-1)[c.queries[i+1],c.queries[i]]=[c.queries[i],c.queries[i+1]];configState.editing=c;renderConfig()});document.getElementById('addQuery').onclick=()=>{const c=readConfig();c.queries.push({kind:'proxmox',query:'',limit:10,maxPages:1,minPrice:null,maxPrice:null});configState.editing=c;renderConfig()};document.getElementById('savePending').onclick=()=>saveConfig().catch(configError);document.getElementById('applyPending').onclick=()=>applyConfig().catch(configError);document.getElementById('discardPending').onclick=()=>discardConfig().catch(configError);document.getElementById('revertApplied').onclick=()=>revertConfig().catch(configError);loadConfig().catch(configError);
</script>`;

const reviewScript = String.raw`<script>
let reviewData={reviews:{}};
const reviewStatuses=${JSON.stringify(REVIEW_STATUSES)};
const reviewEsc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function reviewControls(card){const id=card.dataset.reviewId;const saved=reviewData.reviews[id]||{status:'Unreviewed',notes:'',manualDetails:'',reviewedAt:null};if(card.dataset.reviewMounted){const status=card.querySelector('[data-review-status]');const notes=card.querySelector('[data-review-notes]');const details=card.querySelector('[data-review-details]');if(status)status.value=saved.status;if(notes)notes.value=saved.notes;if(details)details.value=saved.manualDetails;return;}const options=reviewStatuses.map(status=>'<option'+(status===saved.status?' selected':'')+'>'+status+'</option>').join('');card.dataset.reviewMounted='1';const host=card.querySelector('[data-listing-details]')||card;host.insertAdjacentHTML('beforeend','<section class="review-box user-review"><div class="meta"><b>Your review</b> — manual only'+(saved.reviewedAt?' · '+new Date(saved.reviewedAt).toLocaleDateString():'')+'</div><label class="meta">Status <select data-review-status>'+options+'</select></label><textarea data-review-notes placeholder="Your notes (not report facts)">'+reviewEsc(saved.notes)+'</textarea><textarea data-review-details placeholder="Manual verification details (not report facts)">'+reviewEsc(saved.manualDetails)+'</textarea><button type="button" data-save-review>Save review</button><span class="meta" data-review-message></span></section>');}
function decorateReviews(){document.querySelectorAll('[data-review-card]').forEach(reviewControls)}
async function loadReviews(){try{const response=await fetch('/api/state',{cache:'no-store',signal:AbortSignal.timeout(5000)});if(response.ok){const state=await response.json();reviewData.reviews=state.reviews||{};decorateReviews()}}catch{} }
document.addEventListener('click',async(event)=>{const button=event.target.closest('[data-save-review]');if(!button)return;const card=button.closest('[data-review-card]');const message=card.querySelector('[data-review-message]');button.disabled=true;try{const response=await fetch('/api/reviews',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({listingId:card.dataset.reviewId,status:card.querySelector('[data-review-status]').value,notes:card.querySelector('[data-review-notes]').value,manualDetails:card.querySelector('[data-review-details]').value})});const body=await response.json();if(!response.ok)throw new Error(body.error||'Review was not saved.');reviewData.reviews=body.reviews||reviewData.reviews;message.textContent='Saved locally.'}catch(error){message.textContent='Review error: '+error.message}finally{button.disabled=false}});
document.addEventListener('click',async(event)=>{const button=event.target.closest('[data-copy-checklist]');if(!button)return;const message=button.nextElementSibling;try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard access is unavailable in this browser context.');await navigator.clipboard.writeText(button.dataset.checklist||'');message.textContent='Copied locally.'}catch(error){message.textContent='Copy unavailable: '+error.message}});
let bulkHistory=[];
function renderBulkHistory(){const host=$('bulkHistory');if(!host)return;const available=bulkHistory.filter(x=>!x.undoneAt);$('undoBulk').disabled=!available.length;if($('bulkHistoryCount'))$('bulkHistoryCount').textContent=bulkHistory.length+' actions';host.innerHTML=bulkHistory.length?'<b>Recent bulk actions:</b> '+bulkHistory.map(x=>'<span class="change-badge">'+reviewEsc(x.status)+' · '+x.listingIds.length+' listing(s)'+(x.undoneAt?' · undone':'')+(x.undoneAt?'':' <button type="button" data-history-undo="'+reviewEsc(x.id)+'">Undo</button>')+'</span>').join(' '):'No persisted bulk review actions.'}
async function loadBulkHistory(){try{const response=await fetch('/api/reviews/history',{cache:'no-store',signal:AbortSignal.timeout(5000)});const body=await response.json();if(!response.ok)throw new Error(body.error||'Bulk review history could not be loaded.');bulkHistory=body.entries||[];renderBulkHistory();if(body.issues?.length)$('bulkMessage').textContent=body.issues.join(' ')}catch(error){bulkHistory=[];renderBulkHistory();$('bulkMessage').textContent='Bulk history error: '+error.message}}
async function applyBulkReview(){const ids=[...selectedIds];if(!ids.length){$('bulkMessage').textContent='Select one or more listings first.';return}const status=$('bulkStatus').value;if(!confirm('Change '+ids.length+' selected listing(s) to '+status+'? Existing notes and manual verification details will be preserved.'))return;const button=$('applyBulk');button.disabled=true;try{const response=await fetch('/api/reviews/bulk',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({listingIds:ids,status,confirmation:'BULK_REVIEW_CONFIRM'})});const body=await response.json();if(!response.ok)throw new Error(body.error||'Bulk review was not saved.');bulkHistory=body.history||bulkHistory;reviewData.reviews=body.reviews||reviewData.reviews;selectedIds.clear();$('bulkMessage').textContent='Bulk review saved locally. It is now recoverable from persisted history.';renderBulkHistory();await refresh();decorateReviews()}catch(error){$('bulkMessage').textContent='Bulk review error: '+error.message}finally{button.disabled=false}}
async function undoBulkReview(historyId){if(!historyId)return;if(!confirm('Undo this persisted bulk review action? The undo will stop if any selected listing review changed since the action.'))return;const response=await fetch('/api/reviews/undo',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({historyId,confirmation:'UNDO_BULK_REVIEW'})});const body=await response.json();if(!response.ok){$('bulkMessage').textContent='Undo blocked: '+(body.error||'bulk review conflict');return}reviewData.reviews=body.reviews||reviewData.reviews;bulkHistory=body.history||bulkHistory;$('bulkMessage').textContent='Bulk review undone locally; prior status, notes, manual details, and timestamp were restored.';renderBulkHistory();await refresh();decorateReviews()}
document.getElementById('applyBulk').onclick=()=>applyBulkReview();document.getElementById('undoBulk').onclick=()=>undoBulkReview(bulkHistory.find(x=>!x.undoneAt)?.id);document.addEventListener('click',event=>{const button=event.target.closest('[data-history-undo]');if(button)undoBulkReview(button.dataset.historyUndo)});
new MutationObserver(decorateReviews).observe(document.body,{childList:true,subtree:true});loadReviews();loadBulkHistory();
</script>`;

const layoutScript = String.raw`<script>
const layoutStorageKey='hardware-watch-layout-v1';
const layoutDefaults={configuration:false,newSinceLastRun:true,bestMatches:true,diagnostics:false,bulkHistory:false,runHistory:false,freeFinds:false};
const thumbnailStorageKey='hardware-watch-thumbnails-v1';
function applyThumbnailPreference(visible){document.body.classList.toggle('thumbnails-hidden',!visible);const button=$('toggleThumbnails');if(button)button.textContent=visible?'Hide thumbnails':'Show thumbnails'}
function loadThumbnailPreference(){let visible=true;try{visible=JSON.parse(localStorage.getItem(thumbnailStorageKey)||'true')!==false}catch{}applyThumbnailPreference(visible);const button=$('toggleThumbnails');if(button)button.onclick=()=>{const next=!document.body.classList.contains('thumbnails-hidden');applyThumbnailPreference(next);try{localStorage.setItem(thumbnailStorageKey,String(next))}catch{}}}
function applyLayoutPreferences(preferences){document.querySelectorAll('[data-layout-key]').forEach(section=>{const key=section.dataset.layoutKey;section.open=preferences[key]??layoutDefaults[key]??false})}
function loadLayoutPreferences(){let preferences={...layoutDefaults};try{const saved=JSON.parse(localStorage.getItem(layoutStorageKey)||'null');if(saved&&typeof saved==='object')preferences={...preferences,...Object.fromEntries(Object.keys(layoutDefaults).map(key=>[key,saved[key]===true]))}}catch{}applyLayoutPreferences(preferences);document.querySelectorAll('[data-layout-key]').forEach(section=>section.addEventListener('toggle',()=>{try{const saved=JSON.parse(localStorage.getItem(layoutStorageKey)||'{}');saved[section.dataset.layoutKey]=section.open;localStorage.setItem(layoutStorageKey,JSON.stringify(saved))}catch{}}));const restore=$('restoreLayoutDefaults');if(restore)restore.onclick=()=>{try{localStorage.removeItem(layoutStorageKey)}catch{}applyLayoutPreferences({...layoutDefaults});$('bulkMessage').textContent='Layout defaults restored locally.'}}
function updateSummary(){const state=data||{};const changes=state.newSinceLastRun||{newListings:[],updatedListings:[]};const active=$('activeFilters')?.textContent||'Active filters: none';if($('summaryCandidates'))$('summaryCandidates').textContent='Candidates: '+(state.candidates?.length??0);if($('summaryDiagnostics'))$('summaryDiagnostics').textContent='Diagnostics: '+(state.diagnostics?.length??0);if($('summaryNew'))$('summaryNew').textContent='New: '+(changes.newListings?.length??0);if($('summaryUpdated'))$('summaryUpdated').textContent='Updated: '+(changes.updatedListings?.length??0);if($('summaryFilters'))$('summaryFilters').textContent=active.replace('Active filters:','Filters:');if($('newSectionCount'))$('newSectionCount').textContent=(changes.newListings?.length??0)+' new · '+(changes.updatedListings?.length??0)+' updated';if($('bestSectionCount'))$('bestSectionCount').textContent=(state.candidates?.length??0)+' verified';if($('diagnosticsCount'))$('diagnosticsCount').textContent=(state.diagnostics?.length??0)+' items'}
loadLayoutPreferences();
loadThumbnailPreference();
</script>`;

