async function readRequestJson(request: import("node:http").IncomingMessage): Promise<unknown> {
  let body = "";
  for await (const chunk of request) {
    body += String(chunk);
    if (body.length > 1_000_000) throw new Error("Request body is too large.");
  }
  return JSON.parse(body || "{}");
}

const server = createServer(async (request, response) => {
  const sendJson = (status: number, value: unknown) => {
    response.writeHead(status, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" });
    response.end(JSON.stringify(value));
  };
  try {
    if (request.url === "/api/free-finds/scheduler" && request.method === "GET") {
      sendJson(200, await loadFreeFindsScheduler(reportRoot));
      return;
    }
    if (request.url === "/api/free-finds/scheduler" && request.method === "POST") {
      const body = await readRequestJson(request) as { enabled?: unknown; confirmation?: unknown };
      if (typeof body.enabled !== "boolean" || typeof body.confirmation !== "string") { sendJson(400, { error: "Scheduler action requires enabled and explicit confirmation." }); return; }
      try { sendJson(200, await setFreeFindsScheduler(reportRoot, body.enabled, body.confirmation)); } catch (error) { sendJson(400, { error: error instanceof Error ? error.message : String(error), requiredConfirmation: body.enabled ? ENABLE_FREE_FINDS_CONFIRMATION : DISABLE_FREE_FINDS_CONFIRMATION }); }
      return;
    }
    if (request.url === "/api/free-finds/readiness" && (request.method === "GET" || request.method === "POST")) {
      const value = request.method === "POST" ? await readRequestJson(request) : await loadFreeFindsConfig(reportRoot);
      const preview = previewFreeFindsReadiness(value);
      sendJson(preview.ready ? 200 : 400, { preview, error: preview.ready ? undefined : "Free Finds configuration is not ready for a future run." });
      return;
    }
    if (request.url === "/api/free-finds/state" && request.method === "GET") {
      const config = await loadFreeFindsConfig(reportRoot);
      const history = await loadFreeFindsRunHistory(reportRoot);
      const savedListings = await loadFreeFindsListings(reportRoot);
      const reviews = await loadFreeFindsReviews(reportRoot);
      sendJson(200, { config, history, listings: savedListings.listings, attention: summarizeFreeFindsAttention(savedListings.listings, savedListings.health), savedRun: { runAt: savedListings.runAt, status: savedListings.status, message: savedListings.message, issues: savedListings.issues, health: savedListings.health }, reviews: reviews.reviews, reviewIssues: reviews.issues, scheduler: await loadFreeFindsScheduler(reportRoot), plannedRequests: config.queries.reduce((total, query) => total + query.maxPages, 0), estimatedWaitMs: estimateFreeFindsWaitMs(config), mode: "configuration_only" });
      return;
    }
    if (request.url === "/api/free-finds/config" && request.method === "POST") {
      const value = await readRequestJson(request);
      const validationErrors = validateFreeFindsConfig(value);
      if (validationErrors.length) { sendJson(400, { error: validationErrors.join(" "), validationErrors }); return; }
      const config = await saveFreeFindsConfig(reportRoot, value);
      const history = await loadFreeFindsRunHistory(reportRoot);
      const savedListings = await loadFreeFindsListings(reportRoot);
      const reviews = await loadFreeFindsReviews(reportRoot);
      sendJson(200, { config, history, listings: savedListings.listings, attention: summarizeFreeFindsAttention(savedListings.listings, savedListings.health), savedRun: { runAt: savedListings.runAt, status: savedListings.status, message: savedListings.message, issues: savedListings.issues, health: savedListings.health }, reviews: reviews.reviews, reviewIssues: reviews.issues, plannedRequests: config.queries.reduce((total, query) => total + query.maxPages, 0), estimatedWaitMs: estimateFreeFindsWaitMs(config), mode: "configuration_only" });
      return;
    }
    if (request.url === "/api/free-finds/reviews" && request.method === "GET") {
      sendJson(200, await loadFreeFindsReviews(reportRoot));
      return;
    }
    if (request.url === "/api/free-finds/reviews" && request.method === "POST") {
      const body = await readRequestJson(request) as { listingId?: unknown; status?: unknown; pickupStatus?: unknown; pickupNotes?: unknown; pickupAt?: unknown; notes?: unknown };
      sendJson(200, await saveFreeFindsReview(reportRoot, body.listingId, { status: body.status as any, pickupStatus: body.pickupStatus as any, pickupNotes: body.pickupNotes as string, pickupAt: body.pickupAt as string | null, notes: body.notes as string }));
      return;
    }
    if (request.url === "/api/free-finds/reviews/bulk" && request.method === "POST") {
      const body = await readRequestJson(request) as { listingIds?: unknown; status?: unknown; confirmation?: unknown };
      if (body.confirmation !== "FREE_FINDS_BULK_REVIEW_CONFIRM") throw new Error("Explicit confirmation is required for Free Finds bulk review changes.");
      sendJson(200, await saveFreeFindsReviews(reportRoot, body.listingIds, body.status));
      return;
    }
    if (request.url === "/api/config" && request.method === "GET") {
      const state = await loadConfigurationState(reportRoot);
      sendJson(200, { ...state, rateSummary: rateLimitSummary(state.pending ?? state.active) });
      return;
    }
    if (request.url === "/api/config/pending" && request.method === "POST") {
      const config = await readRequestJson(request);
      const errors = validateWatchConfig(config);
      if (errors.length) { sendJson(400, { error: errors.join(" "), validationErrors: errors }); return; }
      const saved = await savePendingConfiguration(reportRoot, config);
      const state = await loadConfigurationState(reportRoot);
      sendJson(200, { ...state, pending: saved.pending, diff: saved.diff, rateSummary: rateLimitSummary(saved.pending) });
      return;
    }
    if (request.url === "/api/config/discard" && request.method === "POST") {
      const body = await readRequestJson(request) as { confirmation?: unknown };
      const state = await discardPendingConfiguration(reportRoot, body.confirmation);
      sendJson(200, { ...state, rateSummary: rateLimitSummary(state.active) });
      return;
    }
    if (request.url === "/api/config/apply" && request.method === "POST") {
      const body = await readRequestJson(request) as { confirmation?: unknown };
      const state = await applyPendingConfiguration(reportRoot, body.confirmation);
      sendJson(200, { ...state, rateSummary: rateLimitSummary(state.active) });
      return;
    }
    if (request.url === "/api/config/revert" && request.method === "POST") {
      const body = await readRequestJson(request) as { confirmation?: unknown };
      const state = await revertLastAppliedConfiguration(reportRoot, body.confirmation);
      sendJson(200, { ...state, rateSummary: rateLimitSummary(state.active) });
      return;
    }
    if (request.url === "/api/reviews" && request.method === "POST") {
      const body = await readRequestJson(request) as { listingId?: unknown; status?: unknown; notes?: unknown; manualDetails?: unknown };
      await saveListingReview(reportRoot, body.listingId, { status: body.status, notes: body.notes, manualDetails: body.manualDetails });
      const state = await loadReviewState(reportRoot);
      sendJson(200, state);
      return;
    }
    if (request.url === "/api/reviews/history" && request.method === "GET") {
      sendJson(200, await loadBulkReviewHistory(reportRoot));
      return;
    }
    if (request.url === "/api/reviews/bulk" && request.method === "POST") {
      const body = await readRequestJson(request) as { listingIds?: unknown; status?: unknown; confirmation?: unknown };
      if (body.confirmation !== "BULK_REVIEW_CONFIRM") throw new Error("Explicit confirmation is required for bulk review changes.");
      const saved = await saveListingReviews(reportRoot, body.listingIds, body.status);
      sendJson(200, { reviews: saved.reviews, issues: saved.issues, historyEntry: saved.historyEntry, history: saved.history });
      return;
    }
    if (request.url === "/api/reviews/undo" && request.method === "POST") {
      const body = await readRequestJson(request) as { historyId?: unknown; confirmation?: unknown };
      if (body.confirmation !== "UNDO_BULK_REVIEW") throw new Error("Explicit confirmation is required to undo a bulk review change.");
      const restored = await undoBulkReview(reportRoot, body.historyId);
      sendJson(200, restored);
      return;
    }
  } catch (error) {
    sendJson(400, { error: error instanceof Error ? error.message : String(error) });
    return;
  }
  if (request.url === "/api/state") {
    const data = await loadDashboardData(reportRoot);
    response.writeHead(200, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" });
    response.end(JSON.stringify(data));
    return;
  }
  if (request.url === "/" || request.url === "/index.html") {
    response.writeHead(200, { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store", "Referrer-Policy": "no-referrer" });
    response.end(dashboardPage);
    return;
  }
  response.writeHead(404, { "Content-Type": "text/plain; charset=utf-8" });
  response.end("Not found\n");
});

server.listen(port, host, () => {
  console.log(`Hardware Deal Watch dashboard: http://${host}:${port}/`);
  console.log(`Reading reports from: ${escapeHtml(reportRoot)}`);
  console.log("Read-only mode: no Facebook/MCP calls and no writes.");
});

process.once("SIGINT", () => server.close(() => process.exit(0)));
process.once("SIGTERM", () => server.close(() => process.exit(0)));
